                    <div className="overflow-x-auto">
                       <table className="w-full text-left text-sm text-zinc-400">
                          <thead className="bg-zinc-950 text-zinc-500 uppercase font-bold text-xs">
                             <tr>
                                <th className="px-6 py-4">Date</th>
                                <th className="px-6 py-4">Item Name</th>
                                <th className="px-6 py-4">Supplier</th>
                                <th className="px-6 py-4 text-center">Qty Added</th>
                                <th className="px-6 py-4 text-right">Unit Cost</th>
                                <th className="px-6 py-4 text-right">Total Spent</th>
                             </tr>
                          </thead>
                          <tbody className="divide-y divide-zinc-800">
                             {supplyTransactions.filter(t => t.itemType === 'INVENTORY').length === 0 ? (
                                <tr><td colSpan={6} className="px-6 py-8 text-center italic text-zinc-600">No purchase history found.</td></tr>
                             ) : (
                                supplyTransactions
                                   .filter(t => t.itemType === 'INVENTORY')
                                   .sort((a,b) => b.date.getTime() - a.date.getTime())
                                   .map((t) => {
                                      const supplierName = suppliers.find(s => s.id === t.supplierId)?.name || 'Unknown Supplier';
                                      return (
                                         <tr key={t.id} className="hover:bg-zinc-800/50 transition-colors">
                                            <td className="px-6 py-4 font-mono text-xs">{format(t.date, 'dd/MM/yyyy HH:mm')}</td>
                                            <td className="px-6 py-4 font-medium text-white">{t.itemName}</td>
                                            <td className="px-6 py-4">
                                               <span className="bg-zinc-800 text-zinc-300 px-2 py-1 rounded text-xs">{supplierName}</span>
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                               <span className="text-emerald-500 font-bold">+{t.quantity}</span>
                                            </td>
                                            <td className="px-6 py-4 text-right text-zinc-500">${t.unitCost.toFixed(2)}</td>
                                            <td className="px-6 py-4 text-right font-bold text-white">${t.totalCost.toFixed(2)}</td>
                                         </tr>
                                      );
                                   })
                             )}
                          </tbody>
                       </table>
                    </div>
                 </div>
              )}

              {inventorySubTab === 'SUPPLIERS' && (
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {suppliers.map(sup => (
                       <div 
                          key={sup.id} 
                          onClick={() => openSupplierDetails(sup)}
                          className="bg-zinc-900 border border-zinc-800 rounded-xl p-6 relative group hover:border-amber-500/50 cursor-pointer transition-all"
                       >
                          <div className="flex items-start gap-4 mb-4">
                             <div className="bg-zinc-800 p-3 rounded-full">
                                <Truck className="w-6 h-6 text-zinc-400 group-hover:text-amber-500" />
                             </div>
                             <div>
                                <h4 className="font-bold text-white text-lg group-hover:text-amber-500 transition-colors">{sup.name}</h4>
                                <span className="text-xs bg-zinc-800 text-zinc-400 px-2 py-0.5 rounded uppercase font-bold">{sup.category}</span>
                             </div>
                          </div>
                          <div className="space-y-2 text-sm text-zinc-400">
                             <p><span className="text-zinc-600">Contact:</span> {sup.contactName || '-'}</p>
                             <p><span className="text-zinc-600">Phone:</span> {sup.phone}</p>
                          </div>
                          <div className="absolute top-4 right-4 flex gap-2">
                             <button 
                                onClick={(e) => {
                                   e.stopPropagation();
                                   deleteSupplier(sup.id);
                                }}
                                className="text-zinc-600 hover:text-red-500 p-2 opacity-0 group-hover:opacity-100 transition-all"
                             >
                                <Trash2 className="w-4 h-4" />
                             </button>
                          </div>
                          <div className="mt-4 flex items-center gap-2 text-xs font-bold text-zinc-500 group-hover:text-white">
                             <Eye className="w-3 h-3" /> View Products & History
                          </div>
                       </div>
                    ))}
                 </div>
              )}
           </div>
        )}

        {/* --- CATEGORIES TAB --- */}
        {activeTab === 'CATEGORIES' && (
           <div className="max-w-4xl space-y-6">
              <div className="bg-zinc-900 border border-zinc-800 rounded-xl p-6">
                 <h3 className="text-white font-bold text-lg mb-4 flex items-center gap-2">
                    <Tag className="w-5 h-5 text-amber-500" /> Category Management
                 </h3>
                 <p className="text-zinc-400 text-sm mb-6">
                    Define standardized categories for your Services, Retail Products, Inventory Supplies, and Suppliers.
                    <br />This prevents typos like "Shampoo" vs "shampoo" and keeps reports clean.
                 </p>

                 {/* Type Switcher */}
                 <div className="flex space-x-2 mb-6 bg-zinc-950 p-1 rounded-lg border border-zinc-800 w-full md:w-max overflow-x-auto">
                    {(['SERVICE', 'PRODUCT', 'SUPPLY', 'SUPPLIER'] as CategoryType[]).map(type => (
                       <button
                          key={type}
                          onClick={() => setCategoryType(type)}
                          className={`px-4 py-2 rounded-md text-xs font-bold transition-all whitespace-nowrap ${
                             categoryType === type ? 'bg-amber-500 text-zinc-900' : 'text-zinc-500 hover:text-white'
                          }`}
                       >
                          {type === 'PRODUCT' ? 'Retail Products' : type.charAt(0) + type.slice(1).toLowerCase() + 's'}
                       </button>
                    ))}
                 </div>

                 {/* Add New Input */}
                 <form onSubmit={handleAddCategory} className="flex gap-2 mb-6">
                    <input 
                       type="text" 
                       placeholder={`New ${categoryType.toLowerCase()} category...`}
                       value={newCategoryName}
                       onChange={e => setNewCategoryName(e.target.value)}
                       className="flex-1 bg-zinc-950 border border-zinc-800 rounded-lg px-4 py-2 text-white focus:border-amber-500 outline-none"
                    />
                    <button 
                       type="submit"
                       disabled={!newCategoryName.trim()}
                       className="bg-amber-500 hover:bg-amber-400 disabled:opacity-50 disabled:cursor-not-allowed text-zinc-900 font-bold px-6 py-2 rounded-lg flex items-center gap-2"
                    >
                       <Plus className="w-4 h-4" /> Add
                    </button>
                 </form>

                 {/* Category List */}
                 <div className="flex flex-wrap gap-2">
                    {categories.filter(c => c.type === categoryType).length === 0 ? (
                       <p className="text-zinc-500 text-sm italic py-4">No categories defined for this section.</p>
                    ) : (
                       categories.filter(c => c.type === categoryType).map(cat => (
                          <div key={cat.id} className="flex items-center gap-2 bg-zinc-950 border border-zinc-800 rounded-lg px-3 py-1.5 group hover:border-amber-500/50 transition-colors">
                             <span className="text-sm font-medium text-white">{cat.name}</span>
                             <button 
                                onClick={() => deleteCategory(cat.id)}
                                className="text-zinc-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                             >
                                <Trash2 className="w-3.5 h-3.5" />
                             </button>
                          </div>
                       ))
                    )}
                 </div>
              </div>
           </div>
        )}

        {/* --- SERVICES TAB --- */}
        {activeTab === 'SERVICES' && (
          <div className="space-y-4 animate-fade-in">
            {services.map((service) => (
              <div key={service.id} className="bg-zinc-900 border border-zinc-800 rounded-xl p-6 flex flex-col md:flex-row md:items-center justify-between gap-4 group hover:border-zinc-700 transition-all">
                <div className="flex-1">
                  <div className="flex items-center gap-3">
                     <h4 className="text-white font-bold text-lg">{service.name}</h4>
                     {service.category && (
                        <span className="text-[10px] bg-zinc-800 text-zinc-400 px-2 py-0.5 rounded uppercase tracking-wider font-bold border border-zinc-700">
                           {service.category}
                        </span>
                     )}
                  </div>
                  <p className="text-zinc-500 text-sm mt-1">ID: {service.id}</p>
                </div>
                <div className="flex items-center gap-6">
                   <div className="text-center">
                    <span className="block text-xs text-zinc-500 mb-1">Duration</span>
                    <span className="text-white font-medium">{service.durationMinutes}m</span>
                   </div>
                   <div className="text-center">
                    <span className="block text-xs text-zinc-500 mb-1">Price</span>
                    <span className="text-amber-500 font-bold">${service.price}</span>
                   </div>

                   {/* ACTIONS */}
                   <div className="flex gap-2 pl-4 border-l border-zinc-800">
                      <button 
                        onClick={() => openEditService(service)}
                        className="p-2 text-zinc-400 hover:text-white hover:bg-zinc-800 rounded-lg transition-all"
                        title="Edit"
                      >
                         <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleDeleteService(service.id)}
                        className="p-2 text-zinc-600 hover:text-red-500 hover:bg-zinc-800 rounded-lg transition-all"
                        title="Delete"
                      >
                         <Trash2 className="w-4 h-4" />
                      </button>
                   </div>
                </div>
              </div>
            ))}
          </div>
        )}

      </div>

      {/* MODALS */}
      <ProductModal isOpen={isProductModalOpen} onClose={() => setIsProductModalOpen(false)} productToEdit={editingProduct} />
      <ServiceModal isOpen={isServiceModalOpen} onClose={() => setIsServiceModalOpen(false)} serviceToEdit={editingService} />
      <InventoryModal isOpen={isInventoryModalOpen} onClose={() => setIsInventoryModalOpen(false)} itemToEdit={editingInventoryItem} />
      <SupplierModal isOpen={isSupplierModalOpen} onClose={() => setIsSupplierModalOpen(false)} />
      <SupplierDetailsModal isOpen={isSupplierDetailsOpen} onClose={() => setIsSupplierDetailsOpen(false)} supplier={selectedSupplier} />

    </div>
  );
};

'use client';


import React, { useState } from 'react';
import { useBarber } from '@/context/BarberContext';
import { useFeatureGate } from '@/hooks/useFeatureGate';
import { 
  Search, 
  UserPlus, 
  Phone, 
  Calendar,
  DollarSign,
  Trophy,
  Star,
  X,
  History,
  FileText,
  Save,
  Clock,
  Cake,
  AlertCircle,
  CalendarCheck,
  Gift,
  Share2,
  MessageSquare,
  Lock,
  Unlock,
  Crown,
  Medal,
  ShieldCheck,
  Sparkles,
  Scissors,
  Users,
  Trash2
} from 'lucide-react';
import { format, differenceInDays } from 'date-fns';
import { AppointmentStatus, Client, Dependent } from '@/types';

export const Clients = () => {
  const { clients, addClient, appointments, updateClient, shopSettings, currentUser, staff } = useBarber();
  const { canUseFeature } = useFeatureGate();

  const hasLoyalty = canUseFeature('LOYALTY');

  const [searchQuery, setSearchQuery] = useState('');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [formData, setFormData] = useState<{name: string, phone: string, email: string, birthDate: string, referrerCode: string, dependents: Dependent[]}>({ 
     name: '', phone: '', email: '', birthDate: '', referrerCode: '', dependents: [] 
  });

  // Dependent Form State
  const [newDependentName, setNewDependentName] = useState('');
  const [newDependentStaffId, setNewDependentStaffId] = useState('');

  // VIEW MODE
  const isOwner = currentUser.role === 'OWNER';
  const [activeTab, setActiveTab] = useState<'PORTFOLIO' | 'HISTORY'>(isOwner ? 'PORTFOLIO' : 'PORTFOLIO');

  // Detail Modal State
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [activeDetailTab, setActiveDetailTab] = useState<'HISTORY' | 'NOTES' | 'DEPENDENTS'>('HISTORY');
  const [noteText, setNoteText] = useState('');

  // STEALTH MODE CHECK
  const canViewContacts = isOwner || !shopSettings.hideClientContactInfo;

  // --- DATA PREPARATION ---
  const myLoyalClients = clients.filter(c => c.preferredStaffId === currentUser.id);
  const myServedClientIds = new Set(
     appointments
        .filter(a => a.staffId === currentUser.id)
        .map(a => a.clientId)
  );

  const myHistoryClients = clients.filter(c => {
     if (c.preferredStaffId === currentUser.id) return false;
     return myServedClientIds.has(c.id);
  });

  let displayedClients: Client[] = [];
  if (isOwner) {
     displayedClients = clients; 
  } else {
     if (activeTab === 'PORTFOLIO') {
        displayedClients = myLoyalClients;
     } else {
        displayedClients = myHistoryClients;
     }
  }

  const filteredClients = displayedClients.filter(c => {
    return (
       c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
       (canViewContacts && c.phone.includes(searchQuery))
    );
  });

  // --- HANDLERS ---

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.phone) return;

    addClient({
      name: formData.name,
      phone: formData.phone,
      email: formData.email, 
      birthDate: formData.birthDate,
      referrerCode: formData.referrerCode,
      dependents: formData.dependents
    });
    setFormData({ name: '', phone: '', email: '', birthDate: '', referrerCode: '', dependents: [] });
    setIsModalOpen(false);
  };

  const handleAddDependent = () => {
     if (newDependentName.trim()) {
        const dep: Dependent = {
           id: Math.random().toString(36).substr(2, 9),
           name: newDependentName,
           preferredStaffId: newDependentStaffId || undefined
        };

        if (selectedClient) {
           // Editing existing client
           const updatedDependents = [...(selectedClient.dependents || []), dep];
           updateClient({ ...selectedClient, dependents: updatedDependents });
           setSelectedClient({ ...selectedClient, dependents: updatedDependents });
        } else {
           // Creating new client
           setFormData(prev => ({ ...prev, dependents: [...prev.dependents, dep] }));
        }
        setNewDependentName('');
        setNewDependentStaffId('');
     }
  };

  const removeDependent = (id: string) => {
     if (selectedClient) {
        const updated = (selectedClient.dependents || []).filter(d => d.id !== id);
        updateClient({ ...selectedClient, dependents: updated });
        setSelectedClient({ ...selectedClient, dependents: updated });
     } else {
        setFormData(prev => ({ ...prev, dependents: prev.dependents.filter(d => d.id !== id) }));
     }
  };

  const handleClientClick = (client: Client) => {
    setSelectedClient(client);
    setNoteText(client.notes || '');
    setActiveDetailTab('HISTORY');
  };

  const saveNotes = () => {
    if (selectedClient) {
      updateClient({ ...selectedClient, notes: noteText });
    }
  };

  const sendWhatsAppMessage = (e: React.MouseEvent, client: Client, type: 'OVERDUE' | 'WINBACK') => {
    e.stopPropagation();
    if (!isOwner) return;

    const daysSince = client.lastVisit ? differenceInDays(new Date(), client.lastVisit) : 0;
    let message = type === 'OVERDUE' ? shopSettings.messageTemplateOverdue : shopSettings.messageTemplateWinBack;
    message = message.replace('{name}', client.name).replace('{days}', daysSince.toString());

    const cleanPhone = client.phone.replace(/\D/g, '');
    const url = `https://wa.me/55${cleanPhone}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  // Get Client History
  const clientHistory = appointments
    .filter(a => a.clientId === selectedClient?.id && a.status === AppointmentStatus.COMPLETED)
    .sort((a, b) => b.date.getTime() - a.date.getTime());

  const getReturnStatus = (lastVisit?: Date) => {
    if (!lastVisit) return { status: 'NEW', days: 0 };
    const daysSince = differenceInDays(new Date(), lastVisit);
    if (daysSince >= shopSettings.winBackDays) return { status: 'LOST', days: daysSince };
    if (daysSince >= shopSettings.returnReminderDays) return { status: 'OVERDUE', days: daysSince };
    if (daysSince >= (shopSettings.returnReminderDays - 7)) return { status: 'WARNING', days: daysSince };
    return { status: 'OK', days: daysSince };
  };

  const getStatusStyles = (status: string) => {
     switch(status) {
        case 'LOST': return 'bg-red-600 border-red-600 hover:border-red-400 text-white';
        case 'OVERDUE': return 'bg-zinc-900 border-red-500/50 hover:border-red-400';
        case 'WARNING': return 'bg-zinc-900 border-amber-500/50 hover:border-amber-400';
        default: return 'bg-zinc-900 border-zinc-800 hover:border-amber-500/50';
     }
  };

  return (
    <div className="h-full flex flex-col animate-fade-in">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
        <div>
          <h2 className="text-3xl font-bold text-white mb-1">Clients</h2>
          <p className="text-zinc-400 text-sm">
             {isOwner ? 'Manage your customer base & loyalty.' : 'Manage your portfolio and relationships.'}
          </p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-amber-500 hover:bg-amber-400 text-zinc-950 font-bold py-2.5 px-6 rounded-xl flex items-center gap-2 transition-all shadow-lg shadow-amber-500/20"
        >
          <UserPlus className="w-5 h-5" /> Add Client
        </button>
      </div>

      {/* TABS (STAFF VIEW) */}
      {!isOwner && (
         <div className="flex space-x-2 bg-zinc-900 p-1 rounded-xl mb-6 border border-zinc-800 w-full md:w-max">
            <button onClick={() => setActiveTab('PORTFOLIO')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${activeTab === 'PORTFOLIO' ? 'bg-zinc-800 text-amber-500 shadow-md ring-1 ring-amber-500/20' : 'text-zinc-500 hover:text-white'}`}><Lock className="w-3 h-3" /> My Portfolio ({myLoyalClients.length})</button>
            <button onClick={() => setActiveTab('HISTORY')} className={`px-6 py-2.5 rounded-lg text-xs font-bold transition-all flex items-center gap-2 ${activeTab === 'HISTORY' ? 'bg-zinc-800 text-blue-400 shadow-md' : 'text-zinc-500 hover:text-white'}`}><Unlock className="w-3 h-3" /> Opportunities / History ({myHistoryClients.length})</button>
         </div>
      )}

      {/* Search */}
      <div className="mb-6 relative">
        <Search className="absolute left-4 top-3.5 w-5 h-5 text-zinc-500" />
        <input 
          type="text"
          placeholder={canViewContacts ? "Search by name or phone..." : "Search by name..."}
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full bg-zinc-900 border border-zinc-800 rounded-xl py-3 pl-12 pr-4 text-white focus:outline-none focus:border-amber-500 transition-all"
        />
      </div>

      {!hasLoyalty && (
        <div className="mb-4 rounded-xl border border-dashed border-amber-500/60 bg-zinc-900/60 p-3 text-[11px] text-amber-200">
          Programa de fidelidade disponível nos planos <strong>Solo PRO</strong> e acima.
        </div>
      )}

      {/* Client List */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 pb-20">
        {filteredClients.map((client) => {
             const returnStatus = getReturnStatus(client.lastVisit);
             const points = client.loyaltyPoints || 0;
             const cardStyle = getStatusStyles(returnStatus.status);
             const isLoyalToMe = client.preferredStaffId === currentUser.id;
             const hasDependents = client.dependents && client.dependents.length > 0;

             const textPrimary = returnStatus.status === 'LOST' ? 'text-white' : 'text-white';
             const textSecondary = returnStatus.status === 'LOST' ? 'text-white/80' : 'text-zinc-400';
             const iconColor = returnStatus.status === 'LOST' ? 'text-white' : 'text-zinc-600';

             return (
               <button 
                 key={client.id} 
                 onClick={() => handleClientClick(client)}
                 className={`text-left rounded-xl p-5 border transition-all group relative overflow-hidden shadow-lg ${cardStyle} ${isLoyalToMe ? 'ring-1 ring-emerald-500/50' : ''}`}
               >
                 <div className="flex justify-between items-start mb-4 relative z-10">
                   <div className="flex items-center gap-3">
                     <div className={`w-12 h-12 rounded-full flex items-center justify-center font-bold text-xl border ${returnStatus.status === 'LOST' ? 'bg-white text-red-600 border-white' : 'bg-zinc-800 text-amber-500 border-zinc-700'}`}>
                       {client.name.charAt(0)}
                     </div>
                     <div>
                       <div className="flex items-center gap-2">
                          <h3 className={`font-bold text-lg ${textPrimary}`}>{client.name}</h3>
                          {isLoyalToMe && <span className="bg-emerald-500 text-zinc-900 text-[9px] font-bold px-1.5 py-0.5 rounded flex items-center gap-1 shadow-sm"><ShieldCheck className="w-2.5 h-2.5" /> MY PORTFOLIO</span>}
                       </div>

                       {hasLoyalty && (
                          <div className={`flex items-center gap-1 text-xs font-bold uppercase tracking-wider ${returnStatus.status === 'LOST' ? 'text-white/80' : (points >= 10 ? 'text-amber-400' : 'text-zinc-500')}`}>
                            {points >= 10 ? <Gift className="w-3 h-3" /> : <Trophy className="w-3 h-3" />}
                            {points >= 10 ? 'Reward Available' : `${points}/10 Stamps`}
                          </div>
                       )}
                     </div>
                   </div>

                   {/* Status Badges */}
                   <div className="flex flex-col items-end gap-2">
                      {returnStatus.status === 'WARNING' && <span className="text-amber-500 text-xs font-bold flex items-center gap-1"><AlertCircle className="w-3 h-3" /> Due Soon</span>}
                      {returnStatus.status === 'OVERDUE' && <div className="flex items-center gap-2"><span className="text-red-400 text-xs font-bold flex items-center gap-1"><Clock className="w-3 h-3" /> {returnStatus.days} Days</span></div>}
                   </div>
                 </div>

                 <div className="space-y-3 mb-6 relative z-10 min-h-[1.5rem]">
                   {canViewContacts ? <div className={`flex items-center gap-3 text-sm ${textSecondary}`}><Phone className={`w-4 h-4 ${iconColor}`} /><span>{client.phone}</span></div> : <div className="h-5"></div>}
                   {hasDependents && (
                      <div className={`flex items-center gap-3 text-xs ${textSecondary}`}>
                         <Users className={`w-4 h-4 ${iconColor}`} />
                         <span>{client.dependents!.length} Dependents</span>
                      </div>
                   )}
                 </div>

                 <div className={`grid grid-cols-2 gap-3 pt-4 border-t relative z-10 ${returnStatus.status === 'LOST' ? 'border-white/20' : 'border-zinc-800'}`}>
                   <div className={`${returnStatus.status === 'LOST' ? 'bg-black/20 text-white' : 'bg-zinc-950/50 text-zinc-200'} rounded-lg p-3`}>
                     <p className="font-medium text-sm">{client.lastVisit ? format(client.lastVisit, 'MMM d') : 'New'}</p>
                   </div>
                   <div className={`${returnStatus.status === 'LOST' ? 'bg-black/20 text-white' : 'bg-zinc-950/50 text-white'} rounded-lg p-3`}>
                     <p className="font-bold text-sm">${client.totalSpent.toFixed(2)}</p>
                   </div>
                 </div>
               </button>
             );
           })
        }
      </div>

      {/* Add Client Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-zinc-900 md:bg-black/70 md:backdrop-blur-sm p-0 md:p-4">
          <div className="bg-zinc-900 w-full h-full md:h-auto md:max-w-md md:rounded-2xl border-0 md:border border-zinc-800 p-6 shadow-2xl overflow-y-auto">
            <div className="flex justify-between items-center mb-6">
               <h3 className="text-xl font-bold text-white">Add New Client</h3>
               <button onClick={() => setIsModalOpen(false)} className="bg-zinc-800 p-2 rounded-full text-zinc-400 hover:text-white"><X className="w-5 h-5"/></button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-6 md:space-y-4">
