interface PlanSummaryCardProps {
  currentPlanId: PlanId | SaasV2PlanId;
}

// Highlights de marketing por plano (resumo visual)
const planHighlights: Record<PlanId, string[]> = {
  FREE: [
    'Agenda básica',
    'Cadastro de clientes',
    'Registro de vendas simples',
  ],
  SOLO: [
    '1 barbeiro',
    'Agenda + Fila Inteligente',
    'PDV e catálogo de serviços',
  ],
  SOLO_PRO: [
    '1 barbeiro com modo empresa',
    'Tudo do Solo',
    'Agendamento Online',
  ],
  EQUIPE: [
    'Até 3 barbeiros',
    'Tudo do Solo PRO',
    'Fidelidade, Comissões, Caixa Cego',
  ],
  STUDIO: [
    'Até 6 barbeiros e 2 unidades',
    'Tudo do Equipe',
    'Website Premium + domínio próprio',
  ],
  ENTERPRISE: [
    'Barbeiros ilimitados',
    'Múltiplas unidades',
    'Gerente de contas dedicado',
  ],
};

const planOrder: PlanId[] = ['FREE', 'SOLO', 'SOLO_PRO', 'EQUIPE', 'STUDIO', 'ENTERPRISE'];

export const PlanSummaryCard: React.FC<PlanSummaryCardProps> = ({ currentPlanId }) => {
  const normalizedPlanId = currentPlanId as PlanId;
  const currentPlan = getPlanDefinition(normalizedPlanId);
  const currentIndex = planOrder.indexOf(normalizedPlanId);
  const nextPlanId = currentIndex >= 0 && currentIndex < planOrder.length - 1
    ? planOrder[currentIndex + 1]
    : undefined;

  const nextPlan = nextPlanId ? getPlanDefinition(nextPlanId) : undefined;

  if (!currentPlan) return null;

  return (
    <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-zinc-50 relative overflow-hidden group">
      {/* Background decoration */}
      <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/5 rounded-full blur-3xl -mr-16 -mt-16 pointer-events-none group-hover:bg-amber-500/10 transition-all duration-1000"></div>

      <div className="flex items-start justify-between gap-4 mb-6 relative z-10">
